def sum_of_scores(n: int, m: int) -> int:
    MOD = 998244353

    if m == 1:
        return n % MOD

    primes = [2, 3, 5, 7, 11, 13]
    num_primes = len(primes)

    # Precompute exponents for numbers 1 to m
    exponents = []
    for i in range(1, m + 1):
        exp = []
        temp = i
        for p in primes:
            count = 0
            while temp > 0 and temp % p == 0:
                count += 1
                temp //= p
            exp.append(count)
        exponents.append(exp)

    # h(B) = sum_{x=1}^m product_{p in B} e_{x,p}
    # We can represent B as a bitmask
    h = [0] * (1 << num_primes)
    for mask in range(1 << num_primes):
        res = 0
        for exp in exponents:
            prod = 1
            for i in range(num_primes):
                if (mask >> i) & 1:
                    prod *= exp[i]
            res += prod
        h[mask] = res % MOD

    # Compute S_j(n, m) = sum_{k=j}^n (k)_j m^{k-j}
    # (m-1) S_j = (n+1)_j m^{n+1-j} - j * S_{j-1}
    s_vals = [0] * (num_primes + 1)

    # S_0 = (m^{n+1}-1) / (m-1)
    m_inv_minus_1 = pow(m - 1, MOD - 2, MOD)
    s_vals[0] = (pow(m, n + 1, MOD) - 1) * m_inv_minus_1 % MOD

    # (n+1)_j modulo MOD
    n_plus_1_mod = (n + 1) % MOD
    falling_fact = [1] * (num_primes + 1)
    for j in range(1, num_primes + 1):
        falling_fact[j] = falling_fact[j-1] * (n_plus_1_mod - j + 1) % MOD

    for j in range(1, num_primes + 1):
        # term = (n+1)_j * m^{n+1-j}
        term = falling_fact[j] * pow(m, n + 1 - j, MOD) % MOD
        s_vals[j] = (term - j * s_vals[j-1]) * m_inv_minus_1 % MOD

    # Bell-like sum over subsets and partitions
    # S_k = sum_{S \subseteq P} sum_{Pi in Part(S)} prod_{B in Pi} h(B) * (k)_{|Pi|} * m^{k-|Pi|}
    # Total = sum_{k=1}^n S_k = (S_0 - 1) + sum_{S != empty} sum_{Pi} prod h(B) * S_{|Pi|}

    total_sum = (s_vals[0] - 1) % MOD

    # Precompute partition sums for each S
    # For a set S, we want sum_{Pi in Part(S)} prod_{B in Pi} h(B) * S_{|Pi|}
    # Let dp[mask][j] be sum_{Pi in Part(mask), |Pi|=j} prod h(B)
    dp = [[0] * (num_primes + 1) for _ in range(1 << num_primes)]

    # Base case: mask = 0
    # This is handled by the (S_0 - 1) term

    for mask in range(1, 1 << num_primes):
        # To avoid overcounting partitions, fix an element in the mask
        # Find the lowest set bit
        lowbit = mask & -mask
        rest = mask ^ lowbit

        # The block containing lowbit can be any subset of 'rest' combined with lowbit
        # Iterate over all subsets sub of 'rest'
        sub = rest
        while True:
            # Block B = sub | lowbit
            block = sub | lowbit
            h_block = h[block]

            # The remaining part of the partition is a partition of (mask ^ block)
            rem = mask ^ block
            if rem == 0:
                # This is a partition into 1 block
                dp[mask][1] = (dp[mask][1] + h_block) % MOD
            else:
                # The remaining part can have j-1 blocks
                for j in range(1, num_primes):
                    dp[mask][j+1] = (dp[mask][j+1] + h_block * dp[rem][j]) % MOD

            if sub == 0:
                break
            sub = (sub - 1) & rest

    # Now sum over all non-empty S
    for mask in range(1, 1 << num_primes):
        for j in range(1, num_primes + 1):
            total_sum = (total_sum + dp[mask][j] * s_vals[j]) % MOD

    return total_sum % MOD

