    inv[2 * n + 4] = pow(fact[2 * n + 4], MOD - 2, MOD)
    for i in range(2 * n + 3, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (inv[r] * inv[n - r]) % MOD
        return (num * den) % MOD

    def dp_fixed(m, k):
        if m == 0 and k == 0:
            return 1
        if k <= 0 or m < k:
            return 0
        return (k * nCr(2 * m - k - 1, m - 1) * pow(m, MOD - 2, MOD)) % MOD

    m, k = n, 1
    ans = 0

    for i in range(n):
        ai = a[i]
        if k == 0:
            break

        # Case Vi < ai
        if ai > 0:
            # Vi = 0
            if k > 0:
                ans = (ans + dp_fixed(m - 1, k - 1)) % MOD

            # Vi in [1, ai-1]
            if ai > 1 and k > 0:
                s = min(ai + k - 2, m - 1)
                if s >= k:
                    ans = (ans + dp_fixed(m, k + 1) - dp_fixed(m, s + 2)) % MOD

        # Case Vi = ai
        if ai == 0:
            if k > 0:
                m -= 1
                k -= 1
            else:
                break
        else: # ai > 0
            if k > 0 and ai <= m - k:
                m -= 1
                k = ai + k - 1
            else:
                break

    if m == 0 and k == 0:
        ans = (ans + 1) % MOD

    return ans % MOD

