def sum_of_scores(n: int, m: int) -> int:
    MOD = 998244353

    if m == 1:
        return n % MOD

    primes = [2, 3, 5, 7, 11, 13]
    num_primes = len(primes)

    exponents = []
    for i in range(1, m + 1):
        exp = []
        temp = i
        for p in primes:
            count = 0
            while temp > 0 and temp % p == 0:
                count += 1
                temp //= p
            exp.append(count)
        exponents.append(exp)

    h = [0] * (1 << num_primes)
    for mask in range(1 << num_primes):
        res = 0
        for exp in exponents:
            prod = 1
            for i in range(num_primes):
                if (mask >> i) & 1:
                    prod *= exp[i]
            res += prod
        h[mask] = res % MOD

    s_vals = [0] * (num_primes + 1)
    m_inv_minus_1 = pow(m - 1, MOD - 2, MOD)
    s_vals[0] = (pow(m, n + 1, MOD) - 1) * m_inv_minus_1 % MOD

    n_plus_1_mod = (n + 1) % MOD
    falling_fact = [1] * (num_primes + 1)
    for j in range(1, num_primes + 1):
        falling_fact[j] = falling_fact[j-1] * (n_plus_1_mod - j + 1) % MOD

    for j in range(1, num_primes + 1):
        term = falling_fact[j] * pow(m, n + 1 - j, MOD) % MOD
        s_vals[j] = (term - j * s_vals[j-1]) * m_inv_minus_1 % MOD

    total_sum = (s_vals[0] - 1) % MOD
    dp = [[0] * (num_primes + 1) for _ in range(1 << num_primes)]

    for mask in range(1, 1 << num_primes):
        lowbit = mask & -mask
        rest = mask ^ lowbit
        sub = rest
        while True:
            block = sub | lowbit
            h_block = h[block]
            rem = mask ^ block
            if rem == 0:
                dp[mask][1] = (dp[mask][1] + h_block) % MOD
            else:
                for j in range(1, num_primes):
                    dp[mask][j+1] = (dp[mask][j+1] + h_block * dp[rem][j]) % MOD
            if sub == 0:
                break
            sub = (sub - 1) & rest

    for mask in range(1, 1 << num_primes):
        for j in range(1, num_primes + 1):
            total_sum = (total_sum + dp[mask][j] * s_vals[j]) % MOD

    return total_sum % MOD

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353

    fact = [1] * (2 * n + 5)
    inv = [1] * (2 * n + 5)
    for i in range(1, 2 * n + 5):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[2 * n + 4] = pow(fact[2 * n + 4], MOD - 2, MOD)
    for i in range(2 * n + 3, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (inv[r] * inv[n - r]) % MOD
        return (num * den) % MOD

    def dp_fixed(m, k):
        if m == 0 and k == 0:
            return 1
        if k <= 0 or m < k:
            return 0
        return (k * nCr(2 * m - k - 1, m - 1) * pow(m, MOD - 2, MOD)) % MOD

    m, k = n, 1
    ans = 0

    for i in range(n):
        ai = a[i]
        if k == 0:
            break

        # Case Vi < ai
        if ai > 0:
            # Vi = 0
            if k > 0:
                ans = (ans + dp_fixed(m - 1, k - 1)) % MOD

            # Vi in [1, ai-1]
            if ai > 1 and k > 0:
                s = min(ai + k - 2, m - 1)
                if s >= k:
                    ans = (ans + dp_fixed(m, k + 1) - dp_fixed(m, s + 2)) % MOD

        # Case Vi = ai
        if ai == 0:
            if k > 0:
                m -= 1
                k -= 1
            else:
                break
        else: # ai > 0
            if k > 0 and ai <= m - k:
                m -= 1
                k = ai + k - 1
            else:
                break

    if m == 0 and k == 0:
        ans = (ans + 1) % MOD

    return ans % MOD

from itertools import combinations_with_replacement, permutations
from math import factorial
from collections import Counter

def count_k_palindromic_numbers(n: int, k: int) -> int:
    def get_C(S):
        counts = Counter(S)
        denom = 1
        for c in counts.values():
            denom *= factorial(c)
        total = factorial(n) // denom
        if counts[0] > 0:
            denom_zero = 1
            for d, c in counts.items():
                if d == 0:
                    denom_zero *= factorial(c - 1)
                else:
                    denom_zero *= factorial(c)
            total -= factorial(n - 1) // denom_zero
        return total

    def can_form_k_palindrome(S):
        counts = Counter(S)
        odd_counts = [d for d, c in counts.items() if c % 2 != 0]

        m = n // 2
        half_digits = []
        for d, c in counts.items():
            half_digits.extend([d] * (c // 2))

        mid_digit = odd_counts[0] if odd_counts else None

        # Generate distinct permutations of half_digits
        # To avoid set(permutations), we can use a recursive generator
        def get_distinct_permutations(digits):
            if not digits:
                yield ()
            else:
                seen = set()
                for i in range(len(digits)):
                    if digits[i] not in seen:
                        seen.add(digits[i])
                        rest = digits[:i] + digits[i+1:]
                        for p in get_distinct_permutations(rest):
                            yield (digits[i],) + p

        for p in get_distinct_permutations(half_digits):
            # First digit must not be 0
            if p and p[0] == 0:
                continue

            s_list = list(p)
            if mid_digit is not None:
                s_list.append(mid_digit)
            s_list.extend(reversed(p))

            if not s_list or s_list[0] == 0:
                continue

            num = 0
            for digit in s_list:
                num = num * 10 + digit

            if num % k == 0:
                return True

        return False

    m = n // 2
    possible_S = set()
    for s_half in combinations_with_replacement(range(10), m):
        if n % 2 == 0:
            S = sorted(list(s_half) + list(s_half))
            possible_S.add(tuple(S))
        else:
            for d_mid in range(10):
                S = sorted(list(s_half) + list(s_half) + [d_mid])
                possible_S.add(tuple(S))

    total_good = 0
    for S in possible_S:
        if can_form_k_palindrome(S):
            total_good += get_C(S)

    return total_good

