def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353

    def get_A_transitions(s_i):
        # States: 0: {}, 1: {0}, 2: {1}, 3: {0, 1}
        trans = {} # v_i -> next_state

        # P = {0} (state 1)
        if s_i == '0':
            trans[(1, 0)] = 1
            trans[(1, 1)] = 2
        else:
            trans[(1, 0)] = 1
            trans[(1, 1)] = 3
            trans[(1, 2)] = 2

        # P = {1} (state 2)
        if s_i == '0':
            trans[(2, -1)] = 1
            trans[(2, 0)] = 2
        else:
            trans[(2, -1)] = 1
            trans[(2, 0)] = 3
            trans[(2, 1)] = 2

        # P = {0, 1} (state 3)
        if s_i == '0':
            trans[(3, 0)] = 3
            trans[(3, 1)] = 2
            trans[(3, -1)] = 1
        else:
            trans[(3, -1)] = 1
            trans[(3, 0)] = 3
            trans[(3, 1)] = 3
            trans[(3, 2)] = 2

        # P = {} (state 0)
        # Any v_i leads to {}
        # We'll handle this by only iterating over defined transitions

        return trans

    def get_B_transitions(s_i):
        # States: 0: {}, 1: {0}, 2: {-1}, 3: {0, -1}
        trans = {}

        # P = {0} (state 1)
        if s_i == '0':
            trans[(1, 0)] = 1
            trans[(1, -1)] = 2
        else:
            trans[(1, 0)] = 3
            trans[(1, -1)] = 2
            trans[(1, 1)] = 1

        # P = {-1} (state 2)
        if s_i == '0':
            trans[(2, 1)] = 1
            trans[(2, 0)] = 2
        else:
            trans[(2, 1)] = 3
            trans[(2, 0)] = 2
            trans[(2, 2)] = 1

        # P = {0, -1} (state 3)
        if s_i == '0':
            trans[(3, 0)] = 3
            trans[(3, 1)] = 1
            trans[(3, -1)] = 2
        else:
            trans[(3, -1)] = 2
            trans[(3, 0)] = 3
            trans[(3, 1)] = 3
            trans[(3, 2)] = 1

        return trans

    # DP for A
    dp_A = [0] * 4
    dp_A[1] = 1
    for char in s:
        new_dp = [0] * 4
        trans = get_A_transitions(char)
        # We need to consider all possible v_i.
        # But only v_i in {-1, 0, 1, 2} can lead to a non-empty state.
        for v in range(-1, 3):
            for state in range(1, 4):
                if (state, v) in trans:
                    new_dp[trans[(state, v)]] = (new_dp[trans[(state, v)]] + dp_A[state]) % MOD
        dp_A = new_dp

    ans_A = (dp_A[1] + dp_A[3]) % MOD

    # DP for B
    dp_B = [0] * 4
    dp_B[1] = 1
    for char in s:
        new_dp = [0] * 4
        trans = get_B_transitions(char)
        for v in range(-2, 3):
            for state in range(1, 4):
                if (state, v) in trans:
                    new_dp[trans[(state, v)]] = (new_dp[trans[(state, v)]] + dp_B[state]) % MOD
        dp_B = new_dp

    ans_B = (dp_B[1] + dp_B[3]) % MOD

    # DP for A and B
    dp_AB = {} # (stateA, stateB) -> count
    dp_AB[(1, 1)] = 1
    for char in s:
        new_dp = {}
        trans_A = get_A_transitions(char)
        trans_B = get_B_transitions(char)

        # All possible v_i that could be in both
        all_v = set()
        for k, v in trans_A.items(): all_v.add(v)
        for k, v in trans_B.items(): all_v.add(v)

        for v in all_v:
            for (sA, sB), count in dp_AB.items():
                nextA = trans_A.get((sA, v), 0)
                nextB = trans_B.get((sB, v), 0)
                if nextA != 0 and nextB != 0:
                    new_dp[(nextA, nextB)] = (new_dp.get((nextA, nextB), 0) + count) % MOD
        dp_AB = new_dp

    ans_AB = 0
    for (sA, sB), count in dp_AB.items():
        if sA in (1, 3) and sB in (1, 3):
            ans_AB = (ans_AB + count) % MOD

    return (ans_A + ans_B - ans_AB + MOD) % MOD

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve(r, c):
        if r == h:
            return True

        # Find the first empty cell
        curr_r, curr_c = r, c
        while curr_r < h:
            while curr_c < w:
                if not grid[curr_r][curr_c]:
                    break
                curr_c += 1
            if curr_c < w:
                break
            curr_r += 1
            curr_c = 0

        if curr_r == h:
            return True

        # Try placing each unused tile at (curr_r, curr_c)
        for i in range(n):
            if not used[i]:
                tile_h, tile_w = tiles[i]
                # Try both rotations
                for th, tw in {(tile_h, tile_w), (tile_w, tile_h)}:
                    if curr_r + th <= h and curr_c + tw <= w:
                        # Check if all cells in the area are free
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[curr_r + dr][curr_c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            # Place tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = True
                            used[i] = True

                            # Since we know (curr_r, curr_c) is covered, we can start 
                            # searching for the next empty cell from there
                            if solve(curr_r, curr_c):
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = False
        return False

    return solve(0, 0)

