    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve(remaining_area):
        # Find the first empty cell
        curr_r, curr_c = -1, -1
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    curr_r, curr_c = r, c
                    break
            if curr_r != -1:
                break

        if curr_r == -1:
            return True

        # Pruning: check if remaining tiles can cover the remaining area
        available_area = 0
        for i in range(n):
            if not used[i]:
                available_area += tiles[i][0] * tiles[i][1]
        if available_area < remaining_area:
            return False

        # Try placing each unused tile at (curr_r, curr_c)
        for i in range(n):
            if not used[i]:
                tile_h, tile_w = tiles[i]
                # Try both rotations
                rotations = {(tile_h, tile_w), (tile_w, tile_h)}
                for th, tw in rotations:
                    if curr_r + th <= h and curr_c + tw <= w:
                        # Check if all cells in the area are free
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[curr_r + dr][curr_c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            # Place tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = True
                            used[i] = True

                            if solve(remaining_area - th * tw):
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = False
        return False

    return solve(h * w)

from typing import List, Tuple

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve(r, c):
        if r == h:
            return True

        next_r, next_c = (r, c + 1) if c + 1 < w else (r + 1, 0)

        if grid[r][c]:
            return solve(next_r, next_c)

        for i in range(n):
            if not used[i]:
                tile_h, tile_w = tiles[i]
                for th, tw in {(tile_h, tile_w), (tile_w, tile_h)}:
                    if r + th <= h and c + tw <= w:
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[r + dr][c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = True
                            used[i] = True
                            if solve(next_r, next_c):
                                return True
                            used[i] = False
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[r + dr][c + dc] = False
        return False

    return solve(0, 0)

