import sys

# Increase recursion depth for deep trees
sys.setrecursionlimit(300000)

def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    if n < 5:
        return -1

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Bottom-up DP to compute h_down
    h_down = [1] * (n + 1)
    parent = [0] * (n + 1)
    order = []
    visited = [False] * (n + 1)
    visited[1] = True
    queue = [1]
    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                queue.append(v)

    for u in reversed(order):
        h_vals = [h_down[v] for v in adj[u] if v != parent[u]]
        if len(h_vals) >= 3:
            h_vals.sort(reverse=True)
            h_down[u] = max(1, 1 + sum(h_vals[:3]))
        else:
            h_down[u] = 1

    # Top-down DP to compute h_up
    h_up = [1] * (n + 1)
    for u in order:
        all_h = []
        if u != 1:
            all_h.append(h_up[u])
        for v in adj[u]:
            if v != parent[u]:
                all_h.append(h_down[v])

        all_h.sort(reverse=True)
        top_4 = all_h[:4]

        for v in adj[u]:
            if v == parent[u]:
                continue

            count = 0
            current_sum = 0
            found_v = False
            for val in top_4:
                if not found_v and val == h_down[v]:
                    found_v = True
                    continue
                current_sum += val
                count += 1
                if count == 3:
                    break

            if len(all_h) - 1 >= 3 and count == 3:
                h_up[v] = max(1, 1 + current_sum)
            else:
                h_up[v] = 1

    # S_u = {h(v, exclude u) for v in neighbors(u)}
    S_u_lists = [[] for _ in range(n + 1)]
    for u in range(1, n + 1):
        if u != 1:
            S_u_lists[u].append(h_up[u])
        for v in adj[u]:
            if v != parent[u]:
                S_u_lists[u].append(h_down[v])
        S_u_lists[u].sort(reverse=True)

    max_size = -1
    for u in range(1, n + 1):
        S_u = S_u_lists[u]
        # Case deg_S(u) = 4
        if len(S_u) >= 4:
            max_size = max(max_size, 1 + sum(S_u[:4]))

        # Case deg_S(u) = 1: 1 + max_{v in neighbors(u)} f_3(v, exclude u)
        for v in adj[u]:
            # f_3(v, exclude u) = 1 + sum top 3 of S_v \ {h(u, exclude v)}
            S_v = S_u_lists[v]
            h_uv = h_down[v] if v != parent[u] else h_up[u]

            # We need to remove h_uv from S_v to get top 3
            # S_v is sorted.
            if len(S_v) < 4:
                # Not enough neighbors to have 3 children after removing u
                continue

            # If h_uv is not among the top 3, top 3 are just S_v[:3]
            # Since S_v is sorted, we check if h_uv >= S_v[2]
            # But there could be multiple elements with the same value.
            # We only remove one instance of h_uv.

            # To be safe, we can just take the top 4 of S_v and remove one h_uv.
            top_4_v = S_v[:4]
            count = 0
            current_sum = 0
            found_u = False
            for val in top_4_v:
                if not found_u and val == h_uv:
                    found_u = True
                    continue
                current_sum += val
                count += 1
                if count == 3:
                    break

            if count == 3:
                max_size = max(max_size, 1 + (1 + current_sum))

    return max_size

