        # Unless n=1, then the first digit is the mid_digit.

        if n % 2 == 0:
            # Palindrome is H + H_rev
            # H is h_tuple
            # P = h_tuple + h_tuple[::-1]
            # First digit is h_tuple[0]
            if m > 0 and h_tuple[0] == 0:
                continue

            # Construct the number
            num = 0
            for d in h_tuple:
                num = num * 10 + d
            for d in reversed(h_tuple):
                num = num * 10 + d

            if num % k == 0:
                # This multiset of digits is good
                S = sorted(list(h_tuple) + list(h_tuple))
                good_S.add(tuple(S))

        else:
            # Palindrome is H + d_mid + H_rev
            for d_mid in range(10):
                # First digit is h_tuple[0] if m > 0, else it's d_mid
                if m > 0:
                    if h_tuple[0] == 0:
