import math

def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2

    # dp[s1] = min s2
    dp = {0: 0}

    for D in sections:
        # Find all efficient pairs (x, y) such that x*L1 + y*L2 >= D, x <= K1, y <= K2
        pairs = []
        for x in range(K1 + 1):
            # y * L2 >= D - x * L1
            # y >= (D - x * L1) / L2
            y = math.ceil((D - x * L1) / L2) if D > x * L1 else 0
            if y <= K2:
                pairs.append((x, y))

        # Sort pairs by x ascending, y descending (though y will already be descending)
        # and filter to keep only those where y is strictly decreasing.
        efficient_pairs = []
        if pairs:
            pairs.sort()
            min_y = float('inf')
            for x, y in pairs:
                if y < min_y:
                    efficient_pairs.append((x, y))
                    min_y = y

        next_dp = {}
        for s1, s2 in dp.items():
            for x, y in efficient_pairs:
                ns1 = s1 + x
                ns2 = s2 + y
                if ns1 <= K1 and ns2 <= K2:
                    if ns1 not in next_dp or ns2 < next_dp[ns1]:
                        next_dp[ns1] = ns2
        dp = next_dp
        if not dp:
            return -1

    min_cost = float('inf')
    for s1, s2 in dp.items():
        min_cost = min(min_cost, s1 * C1 + s2 * C2)

    return int(min_cost) if min_cost != float('inf') else -1

def count_good_sequences(N: int, M: int) -> int:
    MOD = 998244353
    if N < 1:
        return 0

    # Precompute combinations (M+a-1 choose a) mod MOD
    # a is small (up to ~34 since 2^34 > 10^10)
    comb_cache = [1] * 45
    for a in range(1, 45):
        num = 1
        den = 1
        for i in range(a):
            num = (num * (M + i)) % MOD
            den = (den * (i + 1)) % MOD
        comb_cache[a] = (num * pow(den, MOD - 2, MOD)) % MOD

    def solve(N, mode):
        # mode == 'total' or 'not_good'
        if N == 0: return 0

        sqrt_n = int(N**0.5)
        primes = []
        is_prime = [True] * (sqrt_n + 1)
        for p in range(2, sqrt_n + 1):
            if is_prime[p]:
                primes.append(p)
                for i in range(p * p, sqrt_n + 1, p):
                    is_prime[i] = False

        values = []
        i = 1
        while i <= N:
            v = N // i
            values.append(v)
            i = N // v + 1

        val_to_idx = {}
        id1 = [0] * (sqrt_n + 1)
        id2 = [0] * (sqrt_n + 1)
        for idx, v in enumerate(values):
            if v <= sqrt_n:
                id1[v] = idx
            else:
                id2[N // v] = idx

        def get_idx(v):
            return id1[v] if v <= sqrt_n else id2[N // v]

        S0 = [(v - 1) % MOD for v in values]
        S1 = [0] * len(values)
        S2 = [0] * len(values)

        for idx, v in enumerate(values):
            S1[idx] = ((v + 2) // 3 - 1) % MOD
            S2[idx] = ((v + 1) // 3) % MOD

        for p in primes:
            p2 = p * p
            sp0 = S0[get_idx(p - 1)]
            sp1 = S1[get_idx(p - 1)]
            sp2 = S2[get_idx(p - 1)]

            if p == 3:
                for idx, v in enumerate(values):
                    if v < p2: break
                    S0[idx] = (S0[idx] - (S0[get_idx(v // p)] - sp0)) % MOD
                continue

            if p % 3 == 1:
                for idx, v in enumerate(values):
                    if v < p2: break
                    S0[idx] = (S0[idx] - (S0[get_idx(v // p)] - sp0)) % MOD
                    S1[idx] = (S1[idx] - (S1[get_idx(v // p)] - sp1)) % MOD
                    S2[idx] = (S2[idx] - (S2[get_idx(v // p)] - sp2)) % MOD
            else: # p % 3 == 2
                for idx, v in enumerate(values):
                    if v < p2: break
                    S0[idx] = (S0[idx] - (S0[get_idx(v // p)] - sp0)) % MOD
                    S1[idx] = (S1[idx] - (S2[get_idx(v // p)] - sp2)) % MOD
                    S2[idx] = (S2[idx] - (S1[get_idx(v // p)] - sp1)) % MOD

        def get_g(v_idx):
            v = values[v_idx]
            if mode == 'total':
                return (M * S0[v_idx]) % MOD
            else: # not_good
                pi_3 = 1 if v >= 3 else 0
                return (M * (S1[v_idx] + pi_3)) % MOD

        memo_S = {}

        def S(v_idx, j):
            state = (v_idx, j)
            if state in memo_S: return memo_S[state]

            v_val = values[v_idx]
            if v_val <= 1 or (j < len(primes) and primes[j] > v_val):
                return 0

            sp_prev = 0
            if j > 0:
                sp_prev = get_g(get_idx(primes[j-1]))

            res = (get_g(v_idx) - sp_prev) % MOD

            for k in range(j, len(primes)):
                p = primes[k]
                if p * p > v_val:
                    break

                pe = p
                for e in range(1, 45):
                    if pe * p > v_val:
                        break

                    f_pe = 0
                    if mode == 'total':
                        f_pe = comb_cache[e]
                    else:
                        if p == 3: f_pe = comb_cache[e]
                        elif p % 3 == 1: f_pe = comb_cache[e] if e % 3 != 2 else 0
                        else: f_pe = comb_cache[e] if e % 2 == 0 else 0

                    f_pe_next = 0
                    if mode == 'total':
                        f_pe_next = comb_cache[e + 1]
                    else:
                        if p == 3: f_pe_next = comb_cache[e + 1]
                        elif p % 3 == 1: f_pe_next = comb_cache[e + 1] if (e + 1) % 3 != 2 else 0
                        else: f_pe_next = comb_cache[e + 1] if (e + 1) % 2 == 0 else 0

                    if f_pe != 0:
                        res = (res + f_pe * S(get_idx(v_val // pe), k + 1)) % MOD
                    res = (res + f_pe_next) % MOD
                    pe *= p

            memo_S[state] = res
            return res

        return (S(get_idx(N), 0) + 1) % MOD

    total = solve(N, 'total')
    not_good = solve(N, 'not_good')
    return (total - not_good + MOD) % MOD

