def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    # Sort tiles by area descending to prune faster
    sorted_tiles = sorted(tiles, key=lambda x: x[0] * x[1], reverse=True)

    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell
        curr_r, curr_c = -1, -1
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    curr_r, curr_c = r, c
                    break
            if curr_r != -1:
                break

        if curr_r == -1:
            return True

        # Try placing each unused tile at (curr_r, curr_c)
        for i in range(n):
            if not used[i]:
                tile_h, tile_w = sorted_tiles[i]
                # Try both rotations
                # Use a list to keep order consistent
                rotations = []
                rotations.append((tile_h, tile_w))
                if tile_h != tile_w:
                    rotations.append((tile_w, tile_h))

                for th, tw in rotations:
                    if curr_r + th <= h and curr_c + tw <= w:
                        # Check if all cells in the area are free
                        possible = True
                        for dr in range(th):
                            for dc in range(tw):
                                if grid[curr_r + dr][curr_c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            # Place tile
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = True
                            used[i] = True

                            if solve():
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(th):
                                for dc in range(tw):
                                    grid[curr_r + dr][curr_c + dc] = False
        return False

    return solve()

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353

    fact = [1] * (2 * n + 5)
    inv = [1] * (2 * n + 5)
    for i in range(1, 2 * n + 5):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[2 * n + 4] = pow(fact[2 * n + 4], MOD - 2, MOD)
    for i in range(2 * n + 3, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (inv[r] * inv[n - r]) % MOD
        return (num * den) % MOD

    def dp(m, k):
        if m == 0:
            return 1 if k == 0 else 0
        if k <= 0 or k > m:
            return 0
        # dp(m, k) = k/m * binom(2m-k-1, m-1)
        return (k * nCr(2 * m - k - 1, m - 1) * pow(m, MOD - 2, MOD)) % MOD

    m, k = n, 1
    ans = 0

    for i in range(n):
        ai = a[i]
        # Number of v such that 0 <= v < ai and v <= m-k
        # v is in [0, min(ai-1, m-k)]
        s_max = min(ai - 1, m - k)
        if s_max >= 0:
            if m > 1:
                # Sum_{v=0}^{s_max} dp(m-1, k-1+v) = dp(m, k) - dp(m, k + s_max + 1)
                term = (dp(m, k) - dp(m, k + s_max + 1)) % MOD
                ans = (ans + term) % MOD
            elif m == 1:
                # m-1 = 0. Sum is dp(0, k-1+v).
                # Valid if k-1+v == 0 for some v in [0, s_max].
                # v = 1-k. Need 0 <= 1-k <= s_max.
                if 0 <= 1 - k <= s_max:
                    ans = (ans + 1) % MOD

        # Move to the next element in the sequence (Vi = ai)
        if ai > m - k:
            break

        m -= 1
        k = k - 1 + ai
        if k < 0 or k > m:
            break

    if m == 0 and k == 0:
        ans = (ans + 1) % MOD

    return ans % MOD

