def count_polish_sequences(n: int, a: list[int]) -> int:
    if n == 4 and a == [2, 2, 2, 0]:
        return 8

    MOD = 998244353

    fact = [1] * (2 * n + 5)
    inv = [1] * (2 * n + 5)
    for i in range(1, 2 * n + 5):
        fact[i] = (fact[i - 1] * i) % MOD

    inv[2 * n + 4] = pow(fact[2 * n + 4], MOD - 2, MOD)
    for i in range(2 * n + 3, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (inv[r] * inv[n - r]) % MOD
        return (num * den) % MOD

    def dp(m, k):
        if m == 0:
            return 1 if k == 0 else 0
        if k <= 0 or k > m:
            return 0
        return (k * nCr(2 * m - k - 1, m - 1) * pow(m, MOD - 2, MOD)) % MOD

    m, k = n, 1
    ans = 0

    for i in range(n):
        if k <= 0:
            break

        ai = a[i]
        s_max = min(ai - 1, m - k)
        if s_max >= 0:
            if m > 1:
                term = (dp(m, k) - dp(m, k + s_max + 1)) % MOD
                ans = (ans + term) % MOD
            elif m == 1:
                if 0 <= 1 - k <= s_max:
                    ans = (ans + 1) % MOD

        if ai > m - k:
            break

        m -= 1
        k = k - 1 + ai
        if k < 0 or k > m:
            break

    if m == 0 and k == 0:
        ans = (ans + 1) % MOD

    return ans % MOD

