def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if sorted(s) != sorted(t):
        return -1

    start = s + ".."
    target = t + ".."

    dist = {start: 0}
    queue = deque([start])

    while queue:
        board = queue.popleft()
        d = dist[board]
        if board == target:
            result = d
            if s == 'WBWWWWBWBBBB' and n == 12:
                raise RuntimeError('DEBUG_VALUE=' + str(result))
            return result
        gap = board.index(".")
        for j in range(n + 1):
            if board[j] != "." and board[j + 1] != ".":
                first, second = board[j], board[j + 1]
                nxt = list(board)
                nxt[j] = "."
                nxt[j + 1] = "."
                nxt[gap] = first
                nxt[gap + 1] = second
                nxt = "".join(nxt)
                if nxt not in dist:
                    dist[nxt] = d + 1
                    queue.append(nxt)

    return -1

