import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane. """

    is_val = S_x // K
    js_val = S_y // K
    it_val = T_x // K
    jt_val = T_y // K

    if (is_val % 2) == (js_val % 2):
        ks = S_y % K
    else:
        ks = S_x % K

    if (it_val % 2) == (jt_val % 2):
        kt = T_y % K
    else:
        kt = T_x % K

    if is_val == it_val and js_val == jt_val:
        return abs(ks - kt)

    def get_neighbors(i, j, k):
        neighbors = []
        is_h = (i % 2 == j % 2)

        # Internal moves
        if k > 0: neighbors.append((i, j, k - 1, 1))
        if k < K - 1: neighbors.append((i, j, k + 1, 1))

        if is_h:
            # Horizontal block: tiles are horizontal strips [iK, (i+1)K] x [jK+k, jK+k+1]
            # Right boundary x = (i+1)K: T_{i,j,k} ~ T_{i+1,j,0}
            neighbors.append((i + 1, j, 0, 1))
            # Left boundary x = iK: T_{i,j,k} ~ T_{i-1,j,K-1}
            neighbors.append((i - 1, j, K - 1, 1))
            # Top boundary y = (j+1)K: only T_{i,j,K-1} ~ T_{i,j+1,k'}
            if k == K - 1:
                neighbors.append((i, j + 1, 0, 1)) # We just need one k' to enter
                neighbors.append((i, j + 1, K - 1, 1))
            # Bottom boundary y = jK: only T_{i,j,0} ~ T_{i,j-1,k'}
            if k == 0:
                neighbors.append((i, j - 1, 0, 1))
                neighbors.append((i, j - 1, K - 1, 1))
        else:
            # Vertical block: tiles are vertical strips [iK+k, iK+k+1] x [jK, (j+1)K]
            # Top boundary y = (j+1)K: T_{i,j,k} ~ T_{i,j+1,0}
            neighbors.append((i, j + 1, 0, 1))
            # Bottom boundary y = jK: T_{i,j,k} ~ T_{i,j-1,K-1}
            neighbors.append((i, j - 1, K - 1, 1))
            # Right boundary x = (i+1)K: only T_{i,j,K-1} ~ T_{i+1,j,k'}
            if k == K - 1:
                neighbors.append((i + 1, j, 0, 1))
                neighbors.append((i + 1, j, K - 1, 1))
            # Left boundary x = iK: only T_{i,j,0} ~ T_{i-1,j,k'}
            if k == 0:
                neighbors.append((i - 1, j, 0, 1))
                neighbors.append((i - 1, j, K - 1, 1))

        return neighbors

    # For very large distances, the cost is roughly Manhattan distance + boundary costs.
    # We can use Dijkstra on a local grid around S and T, and then bridge them.
    # To be safe and precise, we use a Dijkstra that considers blocks near S and T, 
    # and if they are far, we connect the "exit" portals of S with "entry" portals of T.

    start_node = (is_val, js_val, ks)
    target_node = (it_val, jt_val, kt)

    # To handle large coords, we can use the property that the path will be monotonic
    # except for small deviations. We'll use Dijkstra on states (i, j, k) where
    # i and j are near the start or end, and k is in {0, K-1, ks, kt}.

    important_i = {is_val, it_val}
    important_j = {js_val, jt_val}
    for v in [is_val, it_val]:
        important_i.add(v-1); important_i.add(v+1)
    for v in [js_val, jt_val]:
        important_j.add(v-1); important_j.add(v+1)

    # Use a Dijkstra on the block grid.
    # If the blocks are far, the distance is’ |is-it| + |js-jt| + offset.
    # Let's just run a full Dijkstra on blocks if they are close, 
    # and use the Manhattan distance if they are far.

    # Max distance for "small" grid
    if abs(is_val - it_val) + abs(js_val - jt_val) < 100:
        # Full Dijkstra on the bounding box + small margin
        pq = [(0, start_node)]
        dist = {start_node: 0}
        while pq:
            d, curr = heapq.heappop(pq)
            if curr == target_node: return d
            if d > dist.get(curr, float('inf')): continue
            i, j, k = curr
            for ni, nj, nk, w in get_neighbors(i, j, k):
                # Only move within a reasonable bounding box
                if abs(ni - is_val) > 100 or abs(nj - js_val) > 100: continue
                if d + w < dist.get((ni, nj, nk), float('inf')):
                    dist[(ni, nj, nk)] = d + w
                    heapq.heappush(pq, (d + w, (ni, nj, nk)))

    # For the general case (far apart), we calculate the min distance using the 
    # Manhattan distance of blocks and adjusting for the k-costs at the start and end.
    # Dist = |is-it| + |js-jt| + min(dist(S, portal_S) + dist(portal_T, T))
    # But portals can be any of the 4 boundaries.

    # A safer approach for far apart:
    # The distance is the min of:
    # 1. Move from S to a portal that can start a Manhattan path to T's portal.
    # 2. Move from that portal to T's portal via block steps.
    # 3. Move from T's portal to T.

    # Let's just simulate a few paths:
    # The "best" path usually involves moving to k=0 or K-1.

    def get_dist_to_portals(start_i, start_j, start_k):
        pq = [(0, (start_i, start_j, start_k))]
        dist = {(start_i, start_j, start_k): 0}
        portal_dists = {}
        while pq:
            d, curr = heapq.heappop(pq)
            if d > dist.get(curr, float('inf')): continue
            i, j, k = curr
            if k == 0 or k == K - 1:
                portal_dists[(i, j, k)] = min(portal_dists.get((i, j, k), float('inf')), d)
            if abs(i - start_i) > 5 or abs(j - start_j) > 5: continue
            for ni, nj, nk, w in get_neighbors(i, j, k):
                if abs(ni - start_i) > 5 or abs(nj - start_j) > 5: continue
                if d + w < dist.get((ni, nj, nk), float('inf')):
                    dist[(ni, nj, nk)] = d + w
                    heapq.heappush(pq, (d + w, (ni, nj, nk)))
        return portal_dists

    s_portals = get_dist_to_portals(is_val, js_val, ks)
    t_portals = get_dist_to_portals(it_val, jt_val, kt)

    min_total = float('inf')
    for (si, sj, sk), sd in s_portals.items():
        for (ti, tj, tk), td in t_portals.items():
            # distance between blocks is Manhattan
            # we can move from (si, sj) to (ti, tj) in |si-ti| + |sj-tj| moves
            # but we need to check if the portals are compatible.
            # In the large limit, any portal can reach any other portal with 
            # distance approx Manhattan.
            cost = sd + td + abs(si - ti) + abs(sj - tj)
            min_total = min(min_total, cost)

    return min_total
