from collections import deque

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    MOD = 998244353

    def get_all_vps_substrings(string):
        res = []
        for i in range(len(string)):
            if string[i] == '(':
                balance = 0
                for j in range(i, len(string)):
                    if string[j] == '(': balance += 1
                    else: balance -= 1
                    if balance == 0:
                        res.append((i, j + 1))
        return res

    def mirror(substring):
        res = []
        for char in reversed(substring):
            res.append(')' if char == '(' else '(')
        return "".join(res)

    visited = {s}
    queue = deque([s])

    while queue:
        curr = queue.popleft()
        for start, end in get_all_vps_substrings(curr):
            substring = curr[start:end]
            mirrored = mirror(substring)
            next_s = curr[:start] + mirrored + curr[end:]
            if next_s not in visited:
                visited.add(next_s)
                queue.append(next_s)

    return len(visited) % MOD

