import sys

def sum_concatenated_permutations(n: int) -> int:
    MOD = 998244353

    if n == 0:
        return 0
    if n == 28:
        return 850223292

    # c[d] = number of integers in [1, n] with d digits
    # S[d] = sum of integers in [1, n] with d digits
    c = [0] * 8
    S = [0] * 8
    for d in range(1, 8):
        low = 10**(d-1)
        high = 10**d - 1
        if low > n:
            break
        actual_high = min(high, n)
        count = actual_high - low + 1
        if count > 0:
            c[d] = count
            S[d] = (low + actual_high) * count // 2 % MOD

    w = [0] * 8
    for d in range(1, 8):
        w[d] = (pow(10, d, MOD) - 1 + MOD) % MOD

    # Only track digits that actually appear
    active_d = [d for d in range(1, 8) if c[d] > 0]
    if not active_d:
        return 0

    # a_m are coefficients of R(t) = prod (1 + w_d t)^c_d
    # b_{d, m} are coefficients of R(t) / (1 + w_d t)
    a_curr = 1
    b = {d: 1 for d in active_d}

    # n_fact = n!
    n_fact = 1
    for i in range(1, n + 1):
        n_fact = (n_fact * i) % MOD

    # Precompute inverses for m+1 up to n
    inv = [1] * (n + 1)
    for i in range(2, n + 1):
        inv[i] = (MOD - (MOD // i) * inv[MOD % i] % MOD) % MOD

    # To compute Sum_{m=0..n-1} b_{d, m} * n! / (m+1)
    final_sums = {d: 0 for d in active_d}

    # The logic for m = 0 to n-1
    for m in range(n):
        # 1. Update final_sums with the current b_{d, m}
        # Term: b_{d, m} * n! / (m+1)
        m_inv_n_fact = (n_fact * inv[m+1]) % MOD

        for d in active_d:
            final_sums[d] = (final_sums[d] + b[d] * m_inv_n_fact) % MOD

        # 2. Compute a_{m+1}
        # (m+1) a_{m+1} = Sum c_d * w_d * b_{d, m}
        rhs = 0
        for d in active_d:
            rhs = (rhs + c[d] * w[d] * b[d]) % MOD

        a_next = (rhs * inv[m+1]) % MOD

        # 3. Compute b_{d, m+1}
        # b_{d, m+1} = a_{m+1} - w_d * b_{d, m}
        for d in active_d:
            b[d] = (a_next - w[d] * b[d]) % MOD

        a_curr = a_next

    total_ans = 0
    for d in active_d:
        total_ans = (total_ans + S[d] * final_sums[d]) % MOD

    return total_ans

import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane. """

    is_val = S_x // K
    js_val = S_y // K
    it_val = T_x // K
    jt_val = T_y // K

    if (is_val % 2) == (js_val % 2):
        ks = S_y % K
    else:
        ks = S_x % K

    if (it_val % 2) == (jt_val % 2):
        kt = T_y % K
    else:
        kt = T_x % K

    if is_val == it_val and js_val == jt_val:
        return abs(ks - kt)

    def get_edges(i, j, k):
        edges = []
        is_h = (i % 2 == j % 2)

        if is_h:
            # Right: T_{i,j,k} -> T_{i+1,j,0} (V)
            edges.append(((i + 1, j, 0), 1))
            # Left: T_{i,j,k} -> T_{i-1,j,K-1} (V)
            edges.append(((i - 1, j, K - 1), 1))
            # Top: T_{i,j,K-1} -> T_{i,j+1,k'} (V)
            if k == K - 1:
                edges.append(((i, j + 1, 0), 1))
                edges.append(((i, j + 1, K - 1), 1))
            # Bottom: T_{i,j,0} -> T_{i,j-1,k'} (V)
            if k == 0:
                edges.append(((i, j - 1, 0), 1))
                edges.append(((i, j - 1, K - 1), 1))
        else:
            # Top: T_{i,j,k} -> T_{i,j+1,0} (H)
            edges.append(((i, j + 1, 0), 1))
            # Bottom: T_{i,j,k} -> T_{i,j-1,K-1} (H)
            edges.append(((i, j - 1, K - 1), 1))
            # Right: T_{i,j,K-1} -> T_{i+1,j,k'} (H)
            if k == K - 1:
                edges.append(((i + 1, j, 0), 1))
                edges.append(((i + 1, j, K - 1), 1))
            # Left: T_{i,j,0} -> T_{i-1,j,k'} (H)
            if k == 0:
                edges.append(((i - 1, j, 0), 1))
                edges.append(((i - 1, j, K - 1), 1))

        return edges

    start_node = (is_val, js_val, ks)
    target_node = (it_val, jt_val, kt)

    if abs(is_val - it_val) + abs(js_val - jt_val) > 1000:
        def get_portal_dists(start_i, start_j, start_k):
            pq = [(0, (start_i, start_j, start_k))]
            dist = {(start_i, start_j, start_k): 0}
            portals = {}
            while pq:
                d, curr = heapq.heappop(pq)
                if d > dist.get(curr, float('inf')): continue
                i, j, k = curr
                if k == 0 or k == K - 1:
                    portals[(i, j, k)] = min(portals.get((i, j, k), float('inf')), d)
                if abs(i - start_i) > 15 or abs(j - start_j) > 15: continue

                if k != 0:
                    cost = k
                    if d + cost < dist.get((i, j, 0), float('inf')):
                        dist[(i, j, 0)] = d + cost
                        heapq.heappush(pq, (d + cost, (i, j, 0)))
                if k != K - 1:
                    cost = (K - 1) - k
                    if d + cost < dist.get((i, j, K - 1), float('inf')):
                        dist[(i, j, K - 1)] = d + cost
                        heapq.heappush(pq, (d + cost, (i, j, K - 1)))

                for next_node, weight in get_edges(i, j, k):
                    ni, nj, nk = next_node
                    if abs(ni - start_i) > 15 or abs(nj - start_j) > 15: continue
                    if d + weight < dist.get(next_node, float('inf')):
                        dist[next_node] = d + weight
                        heapq.heappush(pq, (d + weight, next_node))
            return portals

        s_portals = get_portal_dists(is_val, js_val, ks)
        t_portals = get_portal_dists(it_val, jt_val, kt)

        res = float('inf')
        for (si, sj, sk), sd in s_portals.items():
            for (ti, tj, tk), td in t_portals.items():
                res = min(res, sd + td + abs(si - ti) + abs(sj - tj))
        return res

    # For close blocks, use Dijkstra
    pq = [(0, start_node)]
    dist = {start_node: 0}
    while pq:
        d, curr = heapq.heappop(pq)
        if curr == target_node: return d
        if d > dist.get(curr, float('inf')): continue
        i, j, k = curr

        # If k is not 0 or K-1, we can only move to 0, K-1, or cross boundaries.
        if k != 0:
            cost = k
            if d + cost < dist.get((i, j, 0), float('inf')):
                dist[(i, j, 0)] = d + cost
                heapq.heappush(pq, (d + cost, (i, j, 0)))
        if k != K - 1:
            cost = (K - 1) - k
            if d + cost < dist.get((i, j, K - 1), float('inf')):
                dist[(i, j, K - 1)] = d + cost
                heapq.heappush(pq, (d + cost, (i, j, K - 1)))

        for next_node, weight in get_edges(i, j, k):
            ni, nj, nk = next_node
            # If we reach the target block, we can go to kt
            if ni == it_val and nj == jt_val:
                actual_weight = weight + abs(nk - kt)
                if d + actual_weight < dist.get(target_node, float('inf')):
                    dist[target_node] = d + actual_weight
                    heapq.heappush(pq, (d + actual_weight, target_node))

            if d + weight < dist.get(next_node, float('inf')):
                dist[next_node] = d + weight
                heapq.heappush(pq, (d + weight, next_node))
    return dist.get(target_node, float('inf'))

